+	endTime := q.End
+	if endTime.IsZero() {
+		endTime = time.Now()
+	}
+
+	_, span := o.tracer.Start(ctx, spanName,
+		trace.WithTimestamp(startTime),
+		trace.WithSpanKind(trace.SpanKindClient),
+	)
+	defer span.End(trace.WithTimestamp(endTime))
